<style>
    :root {
        --pd-navy: #B0171F;
        --pd-navy2: #B0171F;
        --pd-gold: #CF171F;
        --pd-dark: #111;
        --pd-ink: #4b5a74;
    }

    /* ---------- Breadcrumb ---------- */
    .pd-crumb {
        background: #f8fafc;
        border-bottom: 1px solid rgba(176,23,31,.08);
        padding: 16px 0;
        font-size: 13px;
        letter-spacing: .4px;
    }
    .pd-crumb a { color: var(--pd-navy); text-decoration: none; font-weight: 600; }
    .pd-crumb a:hover { color: var(--pd-gold); }
    .pd-crumb .sep { color: #b0b9c9; margin: 0 8px; }
    .pd-crumb .cur { color: var(--pd-ink); }

    /* ---------- Hero ---------- */
    .pd-hero {
        position: relative;
        overflow: hidden;
        background:
            radial-gradient(1000px 420px at 85% -10%, rgba(207,23,31,.16), transparent 60%),
            radial-gradient(700px 380px at -10% 120%, rgba(207,23,31,.08), transparent 60%),
            linear-gradient(125deg, #041a40 0%, #B0171F 45%, #B0171F 100%);
        padding: 70px 0 90px;
    }
    .pd-hero::before {
        content: ''; position: absolute; inset: 0;
        background-image: radial-gradient(rgba(207,23,31,.14) 1.2px, transparent 1.2px);
        background-size: 26px 26px;
        -webkit-mask-image: linear-gradient(90deg, transparent, #000 30%, #000 70%, transparent);
        mask-image: linear-gradient(90deg, transparent, #000 30%, #000 70%, transparent);
    }
    .pd-hero .container { position: relative; z-index: 2; }
    .pd-kicker {
        display: inline-flex; align-items: center; gap: 8px;
        background: rgba(207,23,31,.14); border: 1px solid rgba(207,23,31,.45);
        color: #ffd057; font-size: 12px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase;
        padding: 6px 16px; border-radius: 50px; margin-bottom: 20px;
    }
    .pd-kicker i { color: var(--pd-gold); }
    .pd-title {
        color: #fff; font-family: 'Nunito'; font-weight: 800;
        font-size: clamp(30px, 4.2vw, 54px); line-height: 1.12; margin: 0 0 16px;
    }
    .pd-client {
        display: flex; align-items: center; gap: 10px;
        color: rgba(255,255,255,.82); font-size: 15px; margin-bottom: 20px;
    }
    .pd-client i { color: var(--pd-gold); }
    .pd-client strong { color: #fff; font-weight: 700; }
    .pd-meta { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 30px; }
    .pd-meta-item {
        display: inline-flex; align-items: center; gap: 8px;
        background: rgba(255,255,255,.08); border: 1px solid rgba(255,255,255,.18);
        backdrop-filter: blur(6px); color: #fff; font-size: 12px; font-weight: 600;
        padding: 6px 15px; border-radius: 50px; letter-spacing: .4px;
    }
    .pd-meta-item i { color: var(--pd-gold); }
    .pd-hero-btns { display: flex; flex-wrap: wrap; gap: 14px; }
    .pd-btn-gold, .pd-btn-ghost {
        display: inline-flex; align-items: center; gap: 10px;
        border-radius: 10px; font-weight: 700; font-size: 15px; padding: 14px 30px;
        transition: all .3s ease; text-decoration: none; border: none;
    }
    .pd-btn-gold {
        background: var(--pd-gold); color: var(--pd-navy) !important;
        box-shadow: 0 14px 30px -10px rgba(207,23,31,.45);
    }
    .pd-btn-gold:hover { background: #fff; color: var(--pd-navy) !important; transform: translateY(-3px); }
    .pd-btn-ghost {
        background: rgba(255,255,255,.1); border: 1.5px solid rgba(255,255,255,.35);
        color: #fff !important; backdrop-filter: blur(6px);
    }
    .pd-btn-ghost:hover { background: var(--pd-gold); border-color: var(--pd-gold); color: var(--pd-navy) !important; transform: translateY(-3px); }

    /* ---------- Stat strip ---------- */
    .pd-stats { position: relative; z-index: 3; margin-top: -46px; }
    .pd-stat-card {
        background: #fff; border-radius: 16px; padding: 26px 22px; height: 100%;
        border: 1px solid rgba(176,23,31,.08);
        box-shadow: 0 24px 50px -22px rgba(176,23,31,.35);
        text-align: center; transition: transform .3s ease;
    }
    .pd-stat-card:hover { transform: translateY(-5px); }
    .pd-stat-ico {
        width: 48px; height: 48px; margin: 0 auto 12px; border-radius: 13px;
        background: linear-gradient(135deg, var(--pd-navy), var(--pd-navy2));
        color: var(--pd-gold); display: grid; place-items: center; font-size: 17px;
        box-shadow: 0 10px 22px -8px rgba(176,23,31,.5);
    }
    .pd-stat-val { color: var(--pd-navy2); font-family: 'Nunito'; font-weight: 800; font-size: 17px; line-height: 1.3; word-break: break-word; }
    .pd-stat-lbl { color: #8a97ab; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: .8px; margin-top: 4px; }

    /* ---------- Main / showcase ---------- */
    .pd-main { background: #ffffff; padding: 80px 0 0; }
    .pd-media-wrap { position: relative; }
    .pd-media-ring {
        position: absolute; z-index: 1; top: -18px; right: -18px; bottom: -18px; left: -18px;
        border: 2px dashed rgba(176,23,31,.22); border-radius: 36px 84px 36px 36px;
        animation: pdSpin 40s linear infinite; pointer-events: none;
    }
    @keyframes pdSpin { 0% { transform: rotate(0); } 100% { transform: rotate(1deg); } }
    .pd-frame {
        position: relative; z-index: 2; border-radius: 24px 74px 24px 24px;
        overflow: hidden; box-shadow: 0 34px 70px -24px rgba(176,23,31,.45);
    }
    .pd-frame img { width: 100%; height: clamp(360px, 44vw, 560px); object-fit: cover; display: block; }
    .pd-frame-chip {
        position: absolute; z-index: 3; right: 18px; bottom: 18px;
        display: inline-flex; align-items: center; gap: 8px;
        background: rgba(176,23,31,.9); color: #fff; font-size: 12px; font-weight: 600;
        padding: 8px 14px; border-radius: 50px; border: 1px solid rgba(207,23,31,.5);
        backdrop-filter: blur(6px);
    }
    .pd-frame-chip i { color: var(--pd-gold); }
    .pd-float-badge {
        position: absolute; z-index: 4; left: -18px; bottom: 34px;
        background: var(--pd-gold); color: var(--pd-navy); border-radius: 16px;
        padding: 14px 20px; box-shadow: 0 18px 40px -14px rgba(207,23,31,.6);
        display: flex; align-items: center; gap: 12px; animation: pdFloat 4s ease-in-out infinite;
    }
    .pd-float-badge .fb-txt { font-family: 'Nunito'; font-weight: 800; font-size: 15px; line-height: 1.15; }
    .pd-float-badge .fb-sub { font-size: 11px; font-weight: 600; opacity: .8; }
    @keyframes pdFloat { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-9px); } }

    /* ---------- Content / info ---------- */
    .pd-content { background: #ffffff; padding: 80px 0 20px; }
    .pd-label {
        color: var(--pd-navy2); font-weight: 700; font-size: 12px; text-transform: uppercase;
        letter-spacing: 1.8px; display: inline-flex; align-items: center; gap: 8px; margin-bottom: 10px;
    }
    .pd-label::before { content: ''; width: 26px; height: 3px; background: linear-gradient(90deg, var(--pd-navy), var(--pd-gold)); border-radius: 4px; }
    .pd-h2 { color: var(--pd-navy2); font-family: 'Nunito'; font-size: clamp(24px, 2.4vw, 33px); font-weight: 800; line-height: 1.2; margin-bottom: 16px; }
    .pd-desc { color: var(--pd-ink); font-size: 15px; line-height: 1.95; }

    .pd-info-card {
